        PrintWriter out = new PrintWriter(outputStream);

        int n = inputReader.nextInt();
        long k = inputReader.nextLong();
        String str = inputReader.next();

        boolean[] letters = new boolean[26];
        List<Node> list = new ArrayList<>(n);
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            Node node = new Node(c, i, n);
            if (letters[c - 'a']) {
                node.isSame = true;
            } else {
                letters[c - 'a'] = true;
            }
            list.add(node);
        }
        for (int i = 0; i < list.size(); i++) {
            Node ai = list.get(i);
            for (int j = i + 1; j < list.size(); j++) {
                Node aj = list.get(j);
                ai.addNext(aj.c - 'a', aj);
            }
        }

        for (Node node : list) {
            find(node);
        }

        long[] totalCountArray = new long[n];
        for (int i = 0; i < n; i++) {
            for (Node node : list) {
                if (!node.isSame) {
                    totalCountArray[i] += node.countArray[i];
                }
            }
        }

        long totalCost = 0L;
        long selectCount = 0L;
        for (int i = n - 1; i >= 0; i--) {
            if (selectCount + totalCountArray[i] < k) {
                totalCost += (long) (n - 1 - i) * totalCountArray[i];
                selectCount += totalCountArray[i];
            } else {
                long over = (selectCount + totalCountArray[i]) - k;
                totalCost += (long) (n - 1 - i) * (totalCountArray[i] - over);
                selectCount += (totalCountArray[i] - over);
                break;
            }
        }

