            this.c = c;
            this.index = index;
            this.nextArray = new Node[26];
            this.countArray = new long[n];
        }

        void addNext(int index, Node node) {
            if (nextArray[index] == null) {
                nextCount++;
                nextArray[index] = node;
                nextList.add(node);
            }
        }
    }

