    for (i in 0 until list.size) {
        val ai = list[i]
        for (j in i + 1 until list.size) {
            val aj = list[j]
            ai.addNext(aj.char - 'a', aj)
        }
    }

    for (node in list) {
        find(node)
    }

    val totalCountArray = LongArray(n)
    for (i in 0 until n) {
        for (node in list) {
            if (!node.isSame) {
                totalCountArray[i] += node.countArray[i]
            }
        }
    }

    var totalCost = 0L
    var selectCount = 0L
    for (i in n - 1 downTo 0) {
        if (selectCount + totalCountArray[i] < k) {
            totalCost += (n - 1 - i) * totalCountArray[i]
            selectCount += totalCountArray[i]
        } else {
            val over = (selectCount + totalCountArray[i]) - k
            totalCost += (n - 1 - i) * (totalCountArray[i] - over)
            selectCount += (totalCountArray[i] - over)
            break
        }
    }

    if (selectCount < k) {
        if (selectCount == k - 1) {
            println(totalCost + n)
        } else {
            println(-1)
        }
    } else {
        println(totalCost)
    }
}

private fun find(node: Node) {
    if (node.hasCul) {
        return
    }

    node.countArray[0]++
    for (next in node.nextList) {
        find(next)
        for (i in 0 until next.countArray.size) {
            if (next.countArray[i] > 0) {
                node.countArray[i + 1] += next.countArray[i]
            }
        }
    }

    node.hasCul = true
}

class Node(var char: Char, var index: Int, n: Int) {
    private val nextArray: Array<Node?> = arrayOfNulls<Node?>(26)
    var hasCul = false
    var isSame = false
    var nextCount = 0
    val nextList = ArrayList<Node>()

    val countArray = LongArray(n)

    override fun toString(): String {
        return "$char"
    }

    fun addNext(index: Int, node: Node) {
        if (nextArray[index] == null) {
            nextCount++
            nextArray[index] = node
            nextList.add(node)
        }
    }
}

class InputReader(stream: InputStream) {
    private var reader: BufferedReader = BufferedReader(InputStreamReader(stream))
    private var tokenizer = StringTokenizer("")

    /** get next word  */
    @Throws(IOException::class)
    operator fun next(): String {
        while (!tokenizer.hasMoreTokens()) {
            //TODO add check for eof if necessary
            tokenizer = StringTokenizer(
                reader.readLine()
            )
        }
        return tokenizer.nextToken()
    }

    fun nextLong() = next().toLong()
    fun nextInt() = next().toInt()
    fun nextDouble() = next().toDouble()
    fun nextFloat() = next().toFloat()
}
